// This file is generated by AI.

// Git 状态刷新: 拉取仓库状态写入 store, 并监听项目文件变化防抖刷新。
//
// 监听本身来自 `lib/project-watch.ts` 那条**共享**的项目级监听 (磁盘变更同步也订阅同一条),
// 这里只负责"事件 -> 防抖 -> 重跑 git status"。

import { gitStatus } from '../commands/git';
import { onProjectFilesChanged, startProjectWatch, stopProjectWatch } from '../lib/project-watch';
import { useAppStore } from '../state/store.svelte';

let timer: ReturnType<typeof setTimeout> | null = null;
/** 退订共享监听 (与"监听有没有真的起来"是两件事: 订阅先于启动登记)。 */
let unsubscribe: (() => void) | null = null;
let activePath: string | null = null;

/** 拉取仓库状态并写入 store (仅当仍是当前项目)。 */
export async function refreshGitStatus(path: string): Promise<void> {
  try {
    const status = await gitStatus(path);
    if (useAppStore.getState().projectPath === path) {
      useAppStore.getState().setGitStatus(status);
    }
  } catch {
    if (useAppStore.getState().projectPath === path) {
      useAppStore.getState().setGitStatus(null);
    }
  }
}

/** 开始监听项目根目录 (递归), 文件变更后防抖刷新 git 状态。 */
export async function startGitWatcher(path: string): Promise<void> {
  if (activePath === path && unsubscribe) return;
  await stopGitWatcher();
  activePath = path;
  // 先登记订阅再启动监听: 启动是异步的, 反过来会漏掉启动期间的事件
  unsubscribe = onProjectFilesChanged(scheduleRefresh);
  await startProjectWatch(path);
}

function scheduleRefresh(): void {
  if (timer) clearTimeout(timer);
  timer = setTimeout(() => {
    timer = null;
    const root = activePath;
    if (root) void refreshGitStatus(root);
  }, 400);
}

/** 停止监听并清理计时器。 */
export async function stopGitWatcher(): Promise<void> {
  activePath = null;
  unsubscribe?.();
  unsubscribe = null;
  if (timer) {
    clearTimeout(timer);
    timer = null;
  }
  stopProjectWatch();
}
